package com.internhub.controller;
import com.internhub.dto.*; import com.internhub.security.DatabaseUserPrincipal; import com.internhub.service.ProfileService; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class ProfileController {private final ProfileService service;public ProfileController(ProfileService s){service=s;} @GetMapping("/students/me") public ProfileResponses.Student student(@AuthenticationPrincipal DatabaseUserPrincipal p){return service.student(p.getId());} @PutMapping("/students/me") public ProfileResponses.Student updateStudent(@AuthenticationPrincipal DatabaseUserPrincipal p,@Valid @RequestBody StudentProfileRequest r){return service.updateStudent(p.getId(),r);} @GetMapping("/companies/me") public ProfileResponses.Company company(@AuthenticationPrincipal DatabaseUserPrincipal p){return service.company(p.getId());} @PutMapping("/companies/me") public ProfileResponses.Company updateCompany(@AuthenticationPrincipal DatabaseUserPrincipal p,@Valid @RequestBody CompanyProfileRequest r){return service.updateCompany(p.getId(),r);} @GetMapping("/students/me/dashboard") public ProfileResponses.Dashboard studentDashboard(@AuthenticationPrincipal DatabaseUserPrincipal p){return service.studentDashboard(p.getId());} @GetMapping("/companies/me/dashboard") public ProfileResponses.Dashboard companyDashboard(@AuthenticationPrincipal DatabaseUserPrincipal p){return service.companyDashboard(p.getId());}}
